<script setup lang="ts">
import { CheckCircle2, ChevronLeft, ClipboardCheck, LoaderCircle, QrCode, ScanLine, XCircle } from '@lucide/vue'
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
import { useAuthStore } from '../stores/auth'
import { useLocaleStore } from '../stores/locale'

const router=useRouter();const auth=useAuthStore();const locale=useLocaleStore();const loading=ref(true);const saving=ref(false);const scanning=ref(false);const groups=ref<any[]>([]);const sessions=ref<any[]>([]);const selected=ref<any>(null);const code=ref('');const feedback=ref<{ok:boolean;message:string}|null>(null);const error=ref('');const createOpen=ref(false);const form=ref({teaching_group_id:'',session_date:new Date().toISOString().slice(0,10),starts_at:'',ends_at:''})
const openSessions=computed(()=>sessions.value.filter(item=>item.status==='open'))
async function load(){loading.value=true;try{const [groupResponse,sessionResponse]=await Promise.all([api.get('/teaching-groups'),api.get('/attendance/sessions')]);groups.value=groupResponse.data.groups;sessions.value=sessionResponse.data.sessions;selected.value=openSessions.value[0]||sessions.value[0]||null}finally{loading.value=false}}
async function createSession(){saving.value=true;error.value='';try{const response=await api.post('/attendance/sessions',{...form.value,teaching_group_id:Number(form.value.teaching_group_id)});sessions.value.unshift(response.data.session);selected.value=response.data.session;createOpen.value=false}catch(e:any){error.value=e.response?.data?.message||'Unable to create this attendance session.'}finally{saving.value=false}}
async function scan(){if(!selected.value||!code.value.trim())return;scanning.value=true;feedback.value=null;try{const response=await api.post(`/attendance/sessions/${selected.value.id}/scan`,{student_code:code.value.trim()});feedback.value={ok:true,message:response.data.duplicate?'Already recorded — duplicate safely ignored.':`Checked in ${response.data.record.student?.name_en||response.data.record.student?.name_ar||code.value.trim()}.`};code.value=''}catch(e:any){feedback.value={ok:false,message:e.response?.data?.message||'Student was not found in this group.'}}finally{scanning.value=false}}
async function closeSession(){if(!selected.value)return;await api.post(`/attendance/sessions/${selected.value.id}/close`);selected.value.status='closed';const item=sessions.value.find(row=>row.id===selected.value.id);if(item)item.status='closed'}
onMounted(load)
</script>
<template><div class="app-shell teacher-shell attendance-workspace"><main class="dashboard-main"><header><button class="button secondary back-button" @click="router.push('/teacher/overview')"><ChevronLeft/>{{locale.tr('Teacher workspace')}}</button><div class="header-actions"><span class="teacher-centre-pill"><QrCode/>{{locale.tr('ATTENDANCE DESK')}}</span></div></header><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Preparing attendance desk…')}}</div><div v-else class="dashboard-content teacher-content"><div class="teacher-page-head"><div><span>{{locale.tr('FAST CLASSROOM FLOW')}}</span><h1>{{locale.tr('Attendance desk')}}</h1><p>{{locale.tr('Open a group session, then scan each student code. Duplicate scans are safely ignored.')}}</p></div><button class="button primary" @click="createOpen=true"><QrCode/>Start session</button></div><div v-if="error" class="form-error">{{error}}</div><section class="attendance-grid"><aside class="teacher-card attendance-sessions"><div class="teacher-card-head"><div><small>{{locale.tr('RECENT SESSIONS')}}</small><h2>{{locale.tr('Choose a session')}}</h2></div><ClipboardCheck/></div><button v-for="session in sessions" :key="session.id" class="session-item" :class="{selected:selected?.id===session.id}" @click="selected=session"><span><b>{{session.group?.name_en||session.group?.name_ar||'Group'}}</b><small>{{session.session_date}} · {{session.records_count||0}} scans</small></span><em :class="session.status">{{session.status}}</em></button><div v-if="!sessions.length" class="teacher-empty compact"><QrCode/><b>{{locale.tr('No sessions yet')}}</b><p>Start the first session for one of your groups.</p></div></aside><section class="attendance-console"><div v-if="selected" class="attendance-console-card"><div class="console-head"><div><small>{{selected.group?.code||'GROUP'}} · {{selected.session_date}}</small><h2>{{selected.group?.name_en||selected.group?.name_ar||'Attendance session'}}</h2></div><em :class="selected.status">{{selected.status}}</em></div><div v-if="selected.status==='open'" class="scanner-panel"><span><ScanLine/></span><h3>{{locale.tr('Scan student code')}}</h3><p>{{locale.tr('Use a USB scanner or type the code manually.')}}</p><form @submit.prevent="scan"><input v-model="code" autofocus placeholder="STU-000001" autocomplete="off"><button class="button primary" :disabled="scanning"><LoaderCircle v-if="scanning" class="spin"/><QrCode v-else/>{{scanning?'Checking…':'Record attendance'}}</button></form></div><div v-if="feedback" class="scan-feedback" :class="feedback.ok?'ok':'bad'"><CheckCircle2 v-if="feedback.ok"/><XCircle v-else/>{{feedback.message}}</div><div v-else-if="selected.status==='closed'" class="teacher-empty compact"><CheckCircle2/><b>Session closed</b><p>This session is locked and ready for reporting.</p></div><button v-if="selected.status==='open'" class="button secondary close-session" @click="closeSession">Close session</button></div><div v-else class="teacher-card teacher-list-empty"><QrCode/><h2>{{locale.tr('Select or start a session')}}</h2><p>Attendance records stay attached to the selected teaching group and centre.</p></div></section></section></div></main><div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><section class="centre-modal" role="dialog"><button class="modal-close" @click="createOpen=false"><X/></button><span class="modal-icon"><QrCode/></span><span class="eyebrow">{{locale.tr('NEW ATTENDANCE SESSION')}}</span><h2>{{locale.tr('Start a group session')}}</h2><form @submit.prevent="createSession"><label>Teaching group<select v-model="form.teaching_group_id" required><option value="" disabled>Select a group</option><option v-for="group in groups" :key="group.public_id" :value="group.id">{{group.name_en||group.name_ar}} · {{group.code}}</option></select></label><label>Date<input v-model="form.session_date" type="date" required></label><div class="modal-grid"><label>Starts<input v-model="form.starts_at" type="time"></label><label>Ends<input v-model="form.ends_at" type="time"></label></div><div class="modal-actions"><button type="button" class="button secondary" @click="createOpen=false">Cancel</button><button class="button primary" :disabled="saving">{{saving?'Starting…':'Start session'}}<QrCode/></button></div></form></section></div></div></template>
